parameters.jsCode:
// One item per PDF attachment, and nothing else.
//
// A supplier email carries a logo, a signature image and sometimes a scanned
// delivery note. Handing all of those to the PDF extractor costs a call each
// and produces items with no invoice in them.
//
// single-item input: the trigger fires once per message.
const msg = $('Watch The Invoice Label').first();
const j = msg.json || {};
const bin = msg.binary || {};

function fromAddress(f) {
  if (!f) { return ''; }
  if (typeof f === 'string') { return f; }
  if (f.value && f.value.length) { return String(f.value[0].address || ''); }
  return String(f.text || '');
}

const out = [];
for (const key of Object.keys(bin)) {
  const b = bin[key] || {};
  const name = String(b.fileName || '');
  const type = String(b.mimeType || '');
  if (type.indexOf('pdf') < 0 && !/\.pdf$/i.test(name)) { continue; }
  out.push({
    json: {
      attachment: key,
      file_name: name,
      subject: String(j.subject || ''),
      from: fromAddress(j.from),
      thread_id: String(j.threadId || ''),
      received: String(j.date || '').slice(0, 10),
      has_pdf: true,
    },
    binary: { data: b },
  });
}

// A step that can return nothing ends the branch, and the "no invoice attached"
// path below would never fire.
if (!out.length) {
  return [{ json: { has_pdf: false, subject: String(j.subject || ''), from: fromAddress(j.from) } }];
}
return out;

// Every number on this invoice becomes a number here, in code, not in the
// model.
//
// The same total prints as 1.234,50 in Amsterdam and 2,600.00 in Austin.
// `parseFloat('1.234,50'.replace(/,/g, ''))` is 1.234 - a thousand euro invoice
// that reconciles as one euro twenty-three - and `Number('1.234,50')` is NaN.
// Which separator is the decimal one is decided by which comes last, which is
// true of every format either country writes.
function money(raw) {
  let s = String(raw == null ? '' : raw).replace(/[^0-9.,-]/g, '').trim();
  if (!s) { return null; }
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else {
    s = s.replace(/,/g, '');
  }
  const n = Number(s);
  return isFinite(n) ? n : null;
}

// The Information Extractor nests its result under `output` AND throws the rest
// of the item away. Measured on a live run: the extraction came back as
// `{ output: { invoice_number, vendor_name, ... } }` and nothing else, so the
// sender, the subject and the thread id - everything needed to reply - were
// gone one node after they were read. They are picked back up here from the
// extraction step, which keeps them because `keepSource` is set on it.
const context = $('Read The PDF').all();
const replies = $input.all();
if (context.length !== replies.length) {
  throw new Error('Read ' + context.length + ' PDFs and got ' + replies.length + ' extractions. They are paired by position.');
}

const out = [];
for (let i = 0; i < replies.length; i++) {
  const src = Object.assign({}, context[i].json || {}, replies[i].json || {});
  const f = (src.output || src) || {};

  const lines = (f.line_items || []).map(function (l) {
    return {
      description: String((l && l.description) || '').slice(0, 120),
      quantity: Number((l && l.quantity) || 0),
      amount: money(l && l.amount_as_printed),
    };
  }).filter(function (l) { return l.amount !== null; });

  const total = money(f.total_as_printed);
  const lineSum = lines.reduce(function (t, l) { return t + l.amount; }, 0);

  out.push({ json: {
    attachment: src.attachment || '',
    file_name: src.file_name || '',
    subject: src.subject || '',
    from: src.from || '',
    thread_id: src.thread_id || '',
    received: src.received || '',
    invoice_number: String(f.invoice_number || '').trim(),
    invoice_date: String(f.invoice_date || '').trim(),
    vendor: String(f.vendor_name || '').trim(),
    po_number: String(f.po_number || '').trim(),
    currency: String(f.currency || '').trim().toUpperCase(),
    total_as_printed: String(f.total_as_printed || ''),
    total: total,
    line_count: lines.length,
    line_sum: Math.round(lineSum * 100) / 100,
    // Line items that do not add up to the total are not automatically wrong -
    // tax and shipping live outside them - but a gap larger than either is a
    // reason to look, and it is the cheapest check available.
    lines_add_up: total === null ? false : Math.abs(lineSum - total) < Math.max(1, total * 0.3),
  }});
}
return out;

// The three-way match, and the three ways it goes wrong.
//
// Read by name rather than from the input: the Merge above is a barrier that
// proves both tables have finished loading, and a purchase order row has a
// `vendor` and an `amount` just like an invoice does - reading the merged
// stream would turn every open PO into an invoice to reconcile.
const cfg = $('Settings').first().json;
const pctTol = Math.max(0, Number(cfg.tolerance_percent) || 0);
const absTol = Math.max(0, Number(cfg.tolerance_amount) || 0);

const SUFFIXES = /\b(bv|b\.v|nv|n\.v|inc|incorporated|ltd|limited|llc|llp|plc|gmbh|ag|sarl|sas|sa|srl|spa|oy|ab|as|aps|pty|co|corp|corporation|company|holdings|group)\b/g;

function vendorKey(name) {
  return String(name || '')
    .toLowerCase()
    .replace(/[.,&'"()\-]/g, ' ')
    .replace(SUFFIXES, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function refKey(ref) {
  return String(ref || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}

const pos = $('Read The Open Purchase Orders').all()
  .map(function (i) { return i.json || {}; })
  .filter(function (p) { return p.po_number; });

const seen = new Map();
for (const row of $('Read The Invoices You Have Seen').all()) {
  const r = row.json || {};
  if (r.invoice_key) { seen.set(String(r.invoice_key), r); }
}

const today = new Date().toISOString().slice(0, 10);
const out = [];

for (const item of $('Parse The Money').all()) {
  const inv = item.json || {};
  if (!inv.invoice_number && inv.total === null) { continue; }

  const vKey = vendorKey(inv.vendor);
  const invoiceKey = (vKey + '|' + refKey(inv.invoice_number)).slice(0, 200);

  let po = null;
  if (inv.po_number) {
    po = pos.find(function (p) { return refKey(p.po_number) === refKey(inv.po_number); }) || null;
  }
  // No reference on the invoice is normal on small suppliers. Fall back to the
  // one open order from that vendor whose amount is closest, rather than to the
  // first one, so two open orders do not silently match the wrong one.
  if (!po && vKey && inv.total !== null) {
    const mine = pos.filter(function (p) { return vendorKey(p.vendor) === vKey; });
    let best = null;
    for (const p of mine) {
      const gap = Math.abs(Number(p.amount || 0) - inv.total);
      if (!best || gap < best.gap) { best = { po: p, gap: gap }; }
    }
    po = best ? best.po : null;
  }

  let verdict = 'clear';
  let reason = '';

  if (seen.has(invoiceKey)) {
    const before = seen.get(invoiceKey);
    verdict = 'duplicate';
    reason = 'Invoice ' + inv.invoice_number + ' from ' + inv.vendor + ' was already recorded on ' + (before.seen_on || 'an earlier run') + ' for ' + (before.amount || '?') + ' ' + (before.currency || '') + '.';
  } else if (!po) {
    verdict = 'no purchase order';
    reason = inv.po_number
      ? 'The invoice quotes ' + inv.po_number + ' and there is no open purchase order with that reference.'
      : 'The invoice quotes no purchase order, and no open order from ' + (inv.vendor || 'this vendor') + ' is close to ' + inv.total_as_printed + '.';
  } else if (inv.total === null) {
    verdict = 'amount';
    reason = 'No total could be read from the PDF. It may be a scan with no text layer.';
  } else if (po.currency && inv.currency && String(po.currency).toUpperCase() !== inv.currency) {
    verdict = 'amount';
    reason = 'The order is in ' + po.currency + ' and the invoice is in ' + inv.currency + '. Nothing here converts currencies.';
  } else {
    const ordered = Number(po.amount || 0);
    const gap = inv.total - ordered;
    const allowed = Math.max(absTol, ordered * pctTol / 100);
    if (Math.abs(gap) > allowed) {
      verdict = 'amount';
      reason = 'The invoice is ' + (gap > 0 ? 'over' : 'under') + ' the order by ' + Math.abs(Math.round(gap * 100) / 100) + ' ' + (inv.currency || '') + '. The order is ' + ordered + ' and tolerance allows ' + Math.round(allowed * 100) / 100 + '.';
    } else if (!inv.lines_add_up) {
      verdict = 'amount';
      reason = 'The line items add up to ' + inv.line_sum + ' but the total says ' + inv.total_as_printed + '.';
    }
  }

  out.push({ json: Object.assign({}, inv, {
    invoice_key: invoiceKey,
    verdict: verdict,
    reason: reason,
    po_number_matched: po ? po.po_number : '',
    po_amount: po ? Number(po.amount || 0) : null,
    po_currency: po ? String(po.currency || '') : '',
    seen_on: today,
  })});
}

if (!out.length) {
  return [{ json: { verdict: 'nothing', invoice_key: '', reason: 'No invoice fields could be read.', seen_on: today } }];
}
return out;

