// The model wrote the note. This puts it back on the invoice row and builds the
// reply that a person will read before sending.
//
// single-item input: one held invoice per run of this branch.
const held = $('Match It Against A Purchase Order').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r.verdict && r.verdict !== 'clear' && r.verdict !== 'nothing'; });

const raw = String(($input.first().json || {}).text || '').trim();
const note = raw.replace(/^["'\s]+|["'\s]+$/g, '').slice(0, 900);

return held.map(function (r) {
  const subject = /^re:/i.test(String(r.subject || '')) ? r.subject : 'Re: ' + (r.subject || 'Your invoice');
  const body = [
    note,
    '',
    'For reference:',
    '  Invoice ' + (r.invoice_number || '(no number)') + ' dated ' + (r.invoice_date || 'unknown'),
    '  Total as printed: ' + (r.total_as_printed || 'unreadable'),
    r.po_number_matched ? '  Matched against purchase order ' + r.po_number_matched + ' for ' + r.po_amount + ' ' + (r.po_currency || '') : '  No purchase order matched',
  ].join('\n');
  return { json: Object.assign({}, r, { reply_subject: subject, reply_body: body, note: note }) };
});
